{'content': "// Print-in-place single-stage planetary gearbox (PETG, 0.4 nozzle, 0.1 layer)
// Axis vertical (Z-up). Designed for supportless printing (<=45deg overhangs).
// Units: mm

$fn = 120;

// ---------------------- Parameters ----------------------
// Gear geometry
m = 1.2;                    // gear module (mm)
pressure_angle = 20;        // degrees
z_sun = 12;
z_planet = 12;
z_ring = z_sun + 2*z_planet; // required for planetary
planets = 3;

gear_h = 8;

// Print-in-place clearances (tuned for PETG)
clear_xy = 0.35;            // radial clearance between moving parts
clear_z  = 0.30;            // axial clearance between moving parts
backlash = 0.25;            // backlash along pitch circle (mm)

// Housing / carrier layout
bottom_thick = 2.0;
carrier_thick = 2.4;

// Top retainers (self-supporting via 45deg tapers)
lip_h = 2.5;                // height of housing inward chamfer lip
lip_inset = 2.2;            // how far the lip constricts the opening

// Shafts / pins
post_r = 3.0;               // fixed center post radius
pin_r  = 2.2;               // planet pin shaft radius
head_h = 2.0;               // conical head height (45deg)

// Wall thickness
wall = 3.0;

// ---------------------- Helper Math (radians) ----------------------
PI2 = 2*PI;

function rad(a) = a*PI/180;
function deg(a) = a*180/PI;
function cosr(a) = cos(deg(a));
function sinr(a) = sin(deg(a));
function atanr(x) = atan(x)*PI/180;
function atan2r(y,x) = atan2(y,x)*PI/180;

function rot2(p, a) = [ p[0]*cosr(a) - p[1]*sinr(a), p[0]*sinr(a) + p[1]*cosr(a) ];

// Involute parameter for given radius
function involute_t(rb, r) = (r <= rb) ? 0 : sqrt((r*r)/(rb*rb) - 1);
function involute_theta(t) = t - atanr(t); // radians

function involute_xy(rb, r) =
    let(t = involute_t(rb, r), th = involute_theta(t))
    [ r*cosr(th), r*sinr(th) ];

function arc_points(r, a0, a1, n) = [
    for (i=[0:n])
        let(a = a0 + (a1-a0)*i/n)
        [ r*cosr(a), r*sinr(a) ]
];

// ---------------------- Involute gear 2D ----------------------
// Generates a 2D external gear outline as a union of teeth + root circle.
// addendum and dedendum are radial, in mm.
module gear2d_external(teeth, module_size, pa_deg=20, addendum=undef, dedendum=undef, backlash_mm=0.0, inv_steps=10, arc_steps=6) {
    rp = module_size*teeth/2;
    pa = rad(pa_deg);

    add = (addendum == undef) ? module_size : addendum;
    ded = (dedendum == undef) ? 1.25*module_size : dedendum;

    // Standard radii
    rb = rp*cos(pa_deg); // base circle radius (cos() uses degrees)
    ra = rp + add;
    rf = max(0.2, rp - ded);

    // tooth thickness at pitch circle
    tooth_thickness = PI*module_size/2 - backlash_mm;
    half_ang = tooth_thickness/(2*rp); // radians

    // involute angle at pitch
    tp = involute_t(rb, rp);
    thp = involute_theta(tp);

    // rotate involute so that at pitch it meets +/- half_ang
    rot = half_ang - thp; // radians

    start_r = max(rb, rf);

    // base involute sample points (unrotated, +y side)
    base_pts = [
        for (i=[0:inv_steps])
            let(r = start_r + (ra-start_r)*i/inv_steps)
                involute_xy(rb, r)
    ];

    // right / left flank points
    right_pts = [ for (p=base_pts) rot2(p, +rot) ];
    left_pts  = [ for (p=base_pts) rot2([p[0], -p[1]], -rot) ];

    // flank start angles at root (for radial segment if rf < rb)
    a_root_r = +rot;
    a_root_l = -rot;

    // end angles at outer radius (compute from last flank points)
    pr = right_pts[len(right_pts)-1];
    pl = left_pts[len(left_pts)-1];
    a_outer_r = atan2r(pr[1], pr[0]);
    a_outer_l = atan2r(pl[1], pl[0]);

    // Build one tooth polygon (CCW)
    tooth_poly = concat(
        // root radial start on right
        (rf < start_r) ? [[ rf*cosr(a_root_r), rf*sinr(a_root_r) ], [ start_r*cosr(a_root_r), start_r*sinr(a_root_r) ]] : [[ rf*cosr(a_root_r), rf*sinr(a_root_r) ]],
        // right involute up
        right_pts,
        // outer arc right->left
        arc_points(ra, a_outer_r, a_outer_l, arc_steps),
        // left involute down (reverse)
        [ for (i=[len(left_pts)-1:-1:0]) left_pts[i] ],
        // root radial back to left root
        (rf < start_r) ? [[ start_r*cosr(a_root_l), start_r*sinr(a_root_l) ], [ rf*cosr(a_root_l), rf*sinr(a_root_l) ]] : [],
        // root arc left->right
        arc_points(rf, a_root_l, a_root_r, arc_steps)
    );

    union() {
        // teeth
        for (i=[0:teeth-1])
            rotate(i*360/teeth)
                polygon(points=tooth_poly);
        // root fill
        circle(r=rf);
    }
}

// A 2D internal gear ring: outer circle minus a gear-shaped hole.
// The hole is generated by an external gear with swapped add/ded to approximate internal tooth form.
module ring2d_internal(teeth, module_size, pa_deg=20, wall_thickness=3, backlash_mm=0.25) {
    rp = module_size*teeth/2;

    add_int = module_size;
    ded_int = 1.25*module_size;

    // Inner boundary radii of an internal gear (material teeth point inward):
    r_hole_max = rp + ded_int; // at tooth roots (largest hole radius)
    r_hole_min = rp - add_int; // at tooth tips (smallest hole radius)

    // Outer radius of housing ring
    r_outer = r_hole_max + wall_thickness;

    difference() {
        circle(r=r_outer);
        // gear-shaped hole approximating internal gear
        gear2d_external(
            teeth=teeth,
            module_size=module_size,
            pa_deg=pa_deg,
            addendum=ded_int,      // swapped
            dedendum=add_int,      // swapped
            backlash_mm=backlash_mm
        );
    }
}

// ---------------------- 3D parts ----------------------
module gear_external_3d(teeth, bore_r, z0, h, module_size=m, pa_deg=pressure_angle, backlash_mm=backlash) {
    translate([0,0,z0])
    difference() {
        linear_extrude(height=h)
            gear2d_external(teeth, module_size, pa_deg=pa_deg, backlash_mm=backlash_mm);
        // bore (vertical, supportless)
        translate([0,0,-0.2]) cylinder(h=h+0.4, r=bore_r);
    }
}

module planet_gear(pos, z0) {
    translate([pos[0], pos[1], 0])
        gear_external_3d(z_planet, bore_r=pin_r+clear_xy, z0=z0, h=gear_h);
}

module sun_gear(z0) {
    gear_external_3d(z_sun, bore_r=post_r+clear_xy, z0=z0, h=gear_h);
}

module carrier(z0) {
    // Carrier disc under the gears; pins fixed to carrier; carrier rotates around fixed post.
    rp_s = m*z_sun/2;
    rp_p = m*z_planet/2;
    center_dist = rp_s + rp_p;

    // Keep carrier within ring; provide clearance to ring teeth
    rp_ring = m*z_ring/2;
    r_ring_tip = rp_ring - m; // approx ring tooth tip radius

    carrier_r = min(r_ring_tip - 1.2, center_dist + (m*z_planet/2 + m) + 1.0);

    // z positions
    z_disc = z0;
    z_disc_top = z0 + carrier_thick;

    // pin heights
    z_pin0 = z_disc_top; 
    pin_shaft_h = ( (z_gears + gear_h) - z_pin0 ) + clear_z; // up to just above gear top

    union() {
        // disc with center bearing hole
        translate([0,0,z_disc])
        difference() {
            cylinder(h=carrier_thick, r=carrier_r);
            // center hole around post
            translate([0,0,-0.2]) cylinder(h=carrier_thick+0.4, r=post_r+clear_xy);
        }

        // lightening cutouts (avoid huge flat area, also reduces drag)
        translate([0,0,z_disc+0.4])
        difference() {
            // nothing: used as a subtraction volume in main union context isn't easy
        }

        // pins + 45deg conical heads capturing planets
        for (i=[0:planets-1]) {
            ang = i*360/planets;
            x = center_dist*cos(ang);
            y = center_dist*sin(ang);

            // pin shaft
            translate([x,y,z_pin0]) cylinder(h=pin_shaft_h, r=pin_r);

            // conical head begins above planet top by clear_z (self-supporting)
            translate([x,y,z_gears + gear_h + clear_z])
                cylinder(h=head_h, r1=pin_r, r2=pin_r+head_h);
        }

        // small top rim on carrier for easy handling (stays below gears)
        rim_r1 = carrier_r - 1.0;
        rim_r2 = carrier_r;
        translate([0,0,z_disc_top])
            difference() {
                cylinder(h=1.2, r=rim_r2);
                cylinder(h=1.2, r=rim_r1);
            }
    }
}

module housing() {
    rp_ring = m*z_ring/2;
    add_int = m;
    ded_int = 1.25*m;
    r_hole_max = rp_ring + ded_int; // max radius of gear-shaped hole
    r_outer = r_hole_max + wall;

    // Inner clearance cylinder below/above gear teeth (smooth walls so nothing snags)
    // Must be slightly larger than r_hole_max to avoid rubbing on tooth roots.
    r_cavity = r_hole_max + 0.6;

    difference() {
        // Outer body
        union() {
            // Bottom plate
            cylinder(h=bottom_thick, r=r_outer);

            // Main outer wall up to top
            translate([0,0,bottom_thick])
                cylinder(h=z_total-bottom_thick, r=r_outer);

            // Fixed center post + 45deg conical head (captures sun & carrier)
            // Post shaft
            translate([0,0,0])
                cylinder(h=z_lip_start, r=post_r);
            // Conical head (45deg)
            translate([0,0,z_lip_start])
                cylinder(h=lip_h, r1=post_r, r2=post_r+lip_h);
        }

        // Hollow interior cavity (below gear teeth)
        translate([0,0,bottom_thick])
            cylinder(h=z_gears-bottom_thick, r=r_cavity);

        // Gear tooth region: subtract internal gear-shaped hole
        translate([0,0,z_gears])
            linear_extrude(height=gear_h)
                gear2d_external(
                    teeth=z_ring,
                    module_size=m,
                    pa_deg=pressure_angle,
                    addendum=ded_int,
                    dedendum=add_int,
                    backlash_mm=backlash+0.15
                );

        // Upper cavity above gear teeth (so gears don't rub the top lip during rotation)
        translate([0,0,z_gears+gear_h])
            cylinder(h=(z_total-(z_gears+gear_h)), r=r_cavity);

        // Self-supporting inward chamfer lip to retain planets/carrier
        // Implemented by subtracting a conical frustum so the remaining material forms the lip.
        translate([0,0,z_lip_start])
            cylinder(h=lip_h+0.02, r1=r_cavity, r2=r_cavity - lip_inset);

        // Anti-elephant-foot chamfer on inner bottom edge
        translate([0,0,bottom_thick-0.01])
            cylinder(h=1.0, r1=r_cavity+0.8, r2=r_cavity);
    }
}

// ---------------------- Assembly Z layout ----------------------
// Compute once for all modules
z_carrier = bottom_thick + clear_z;
z_gears   = z_carrier + carrier_thick + clear_z;
z_lip_start = z_gears + gear_h + clear_z;
z_total = z_lip_start + lip_h;

// ---------------------- Assembly ----------------------
module planetary_gearbox() {
    rp_s = m*z_sun/2;
    rp_p = m*z_planet/2;
    center_dist = rp_s + rp_p;

    // planet centers
    planet_pos = [ for (i=[0:planets-1]) [ center_dist*cos(i*360/planets), center_dist*sin(i*360/planets) ] ];

    // Build the full print-in-place mechanism as separate solids with clearances
    union() {
        housing();
        carrier(z_carrier);
        sun_gear(z_gears);
        for (p=planet_pos) planet_gear(p, z_gears);
    }
}

planetary_gearbox();
"}

{'content': '// Print-in-place single-stage planetary gearbox (PETG, 0.4 nozzle, 0.1mm layer)
// Axis vertical (Z-up). Designed for supportless printing (<=45° overhangs).
// All moving parts are captive with built-in clearances.
// Units: mm

$fn = 140;

// ---------------------- Parameters ----------------------
// Gear set
m = 1.2;                    // module
pressure_angle = 20;        // degrees
z_sun = 12;
z_planet = 12;
z_ring = z_sun + 2*z_planet; // planetary constraint
planets = 3;

g ear_h = 8; // (typo guard; overwritten below)
gear_h = 8;

// Print-in-place clearances (PETG)
clear_xy = 0.35;            // radial clearance for bearings/bores
clear_z  = 0.30;            // axial clearance between stacked parts
backlash = 0.30;            // tooth backlash (mm) for free-running gears

// Housing / carrier
bottom_thick  = 2.0;
carrier_thick = 2.4;

// Top retainers (self-supporting)
lip_h     = 2.6;            // vertical height of top constriction region
lip_inset = 2.6;            // radial inset (lip_inset ~= lip_h gives ~45° wall)

// Shafts / pins
post_r = 3.0;               // fixed center post radius
pin_r  = 2.2;               // planet pin shaft radius
head_h = 2.0;               // pin head (cone) height => 45° when dr=head_h

// Wall thickness
wall = 3.0;

// ---------------------- Helper math (radians) ----------------------
function deg(a) = a*180/PI;
function cosr(a) = cos(deg(a));
function sinr(a) = sin(deg(a));
function atanr(x) = atan(x)*PI/180;
function atan2r(y,x) = atan2(y,x)*PI/180;

function rot2(p, a) = [ p[0]*cosr(a) - p[1]*sinr(a), p[0]*sinr(a) + p[1]*cosr(a) ];

function involute_t(rb, r) = (r <= rb) ? 0 : sqrt((r*r)/(rb*rb) - 1);
function involute_theta(t) = t - atanr(t); // radians
function involute_xy(rb, r) = let(t=involute_t(rb,r), th=involute_theta(t)) [ r*cosr(th), r*sinr(th) ];

function arc_points(r, a0, a1, n) = [
    for (i=[0:n])
        let(a = a0 + (a1-a0)*i/n)
        [ r*cosr(a), r*sinr(a) ]
];

// ---------------------- Involute gear 2D (external) ----------------------
// A practical involute approximation suitable for FDM.
module gear2d_external(teeth, module_size, pa_deg=20,
                       addendum=undef, dedendum=undef,
                       backlash_mm=0.0,
                       inv_steps=10, arc_steps=7) {
    rp = module_size*teeth/2;

    add = (addendum == undef) ? module_size : addendum;
    ded = (dedendum == undef) ? 1.25*module_size : dedendum;

    rb = rp*cos(pa_deg);      // base radius
    ra = rp + add;            // outer radius
    rf = max(0.25, rp - ded); // root radius

    // tooth thickness at pitch circle
    tooth_thickness = PI*module_size/2 - backlash_mm;
    half_ang = tooth_thickness/(2*rp); // radians

    // involute polar angle at pitch
    tp = involute_t(rb, rp);
    thp = involute_theta(tp);

    rot = half_ang - thp;     // radians

    start_r = max(rb, rf);

    base_pts = [
        for (i=[0:inv_steps])
            let(r = start_r + (ra-start_r)*i/inv_steps)
                involute_xy(rb, r)
    ];

    right_pts = [ for (p=base_pts) rot2(p, +rot) ];
    left_pts  = [ for (p=base_pts) rot2([p[0], -p[1]], -rot) ];

    a_root_r = +rot;
    a_root_l = -rot;

    pr = right_pts[len(right_pts)-1];
    pl = left_pts[len(left_pts)-1];
    a_outer_r = atan2r(pr[1], pr[0]);
    a_outer_l = atan2r(pl[1], pl[0]);

    tooth_poly = concat(
        // right root -> start
        (rf < start_r) ? [[ rf*cosr(a_root_r), rf*sinr(a_root_r) ], [ start_r*cosr(a_root_r), start_r*sinr(a_root_r) ]] : [[ rf*cosr(a_root_r), rf*sinr(a_root_r) ]],
        // right involute up
        right_pts,
        // outer arc
        arc_points(ra, a_outer_r, a_outer_l, arc_steps),
        // left involute down
        [ for (i=[len(left_pts)-1:-1:0]) left_pts[i] ],
        // left start -> root
        (rf < start_r) ? [[ start_r*cosr(a_root_l), start_r*sinr(a_root_l) ], [ rf*cosr(a_root_l), rf*sinr(a_root_l) ]] : [],
        // root arc
        arc_points(rf, a_root_l, a_root_r, arc_steps)
    );

    union() {
        for (i=[0:teeth-1])
            rotate(i*360/teeth)
                polygon(points=tooth_poly);
        circle(r=rf);
    }
}

// ---------------------- 3D gear ----------------------
module gear_external_3d(teeth, bore_r, z0, h,
                        module_size=m, pa_deg=pressure_angle,
                        backlash_mm=backlash) {
    translate([0,0,z0])
    difference() {
        linear_extrude(height=h)
            gear2d_external(teeth, module_size, pa_deg=pa_deg, backlash_mm=backlash_mm);
        translate([0,0,-0.25]) cylinder(h=h+0.5, r=bore_r);
    }
}

// ---------------------- Assembly Z layout ----------------------
z_carrier   = bottom_thick + clear_z;
z_gears     = z_carrier + carrier_thick + clear_z;
z_gear_top  = z_gears + gear_h;
z_lip_start = z_gear_top + clear_z;
z_total     = z_lip_start + lip_h;

// ---------------------- Parts ----------------------
module sun_gear() {
    gear_external_3d(z_sun, bore_r=post_r+clear_xy, z0=z_gears, h=gear_h);
}

module planet_gear(pos) {
    translate([pos[0], pos[1], 0])
        gear_external_3d(z_planet, bore_r=pin_r+clear_xy, z0=z_gears, h=gear_h);
}

module carrier() {
    rp_s = m*z_sun/2;
    rp_p = m*z_planet/2;
    center_dist = rp_s + rp_p;

    rp_ring = m*z_ring/2;
    r_ring_tip = rp_ring - m; // approx internal ring tooth tip radius

    // Carrier radius (kept well inside ring tooth tip radius)
    carrier_r = r_ring_tip - 1.2;

    z_disc = z_carrier;
    z_disc_top = z_disc + carrier_thick;

    // Pin shaft ends just above gear top (before the conical head starts)
    z_pin0 = z_disc_top;
    pin_shaft_h = (z_gear_top - z_pin0) + clear_z;

    union() {
        // Disc (bearing hole around fixed post)
        translate([0,0,z_disc])
        difference() {
            cylinder(h=carrier_thick, r=carrier_r);
            translate([0,0,-0.25]) cylinder(h=carrier_thick+0.5, r=post_r+clear_xy);
        }

        // Pins + 45° conical heads (capture planets)
        for (i=[0:planets-1]) {
            ang = i*360/planets;
            x = center_dist*cos(ang);
            y = center_dist*sin(ang);

            // shaft
            translate([x,y,z_pin0]) cylinder(h=pin_shaft_h, r=pin_r);

            // head begins above planet top by clear_z
            translate([x,y,z_gear_top + clear_z])
                cylinder(h=head_h, r1=pin_r, r2=pin_r+head_h);
        }

        // Simple grip rim on top of carrier (still below gears)
        translate([0,0,z_disc_top])
        difference() {
            cylinder(h=1.2, r=carrier_r);
            cylinder(h=1.2, r=carrier_r-1.0);
        }
    }
}

module housing_shell() {
    rp_ring = m*z_ring/2;

    add_int = m;
    ded_int = 1.25*m;

    // Internal gear hole radii
    r_hole_max = rp_ring + ded_int; // largest radius in tooth roots
    r_outer = r_hole_max + wall;

    // Use a cavity radius only slightly larger than tooth-root radius to avoid ledges
    r_cavity = r_hole_max + 0.15;

    difference() {
        // Outer body
        union() {
            cylinder(h=bottom_thick, r=r_outer);
            translate([0,0,bottom_thick]) cylinder(h=z_total-bottom_thick, r=r_outer);
        }

        // Lower smooth cavity (annulus; keep a solid region for the post)
        translate([0,0,bottom_thick])
        difference() {
            cylinder(h=z_gears-bottom_thick, r=r_cavity);
            cylinder(h=z_gears-bottom_thick, r=post_r+0.01);
        }

        // Gear tooth region cavity (internal ring gear via gear-shaped hole)
        translate([0,0,z_gears])
        linear_extrude(height=gear_h)
            gear2d_external(
                teeth=z_ring,
                module_size=m,
                pa_deg=pressure_angle,
                // swapped add/ded to form internal gear hole
                addendum=ded_int,
                dedendum=add_int,
                backlash_mm=backlash+0.15
            );

        // Upper cavity above gears up to start of lip (annulus; keep post)
        translate([0,0,z_gear_top])
        difference() {
            cylinder(h=z_lip_start-z_gear_top, r=r_cavity);
            cylinder(h=z_lip_start-z_gear_top, r=post_r+0.01);
        }

        // Top constriction (45°-ish conical cavity to retain planets/carrier)
        translate([0,0,z_lip_start])
        difference() {
            cylinder(h=lip_h+0.01, r1=r_cavity, r2=r_cavity-lip_inset);
            cylinder(h=lip_h+0.01, r1=post_r+0.01, r2=post_r+0.01);
        }

        // Anti-elephant-foot chamfer on inner bottom edge (kept away from carrier)
        translate([0,0,bottom_thick-0.01])
            cylinder(h=0.9, r1=r_cavity+0.8, r2=r_cavity);
    }
}

module housing_post_and_cap() {
    // Fixed center post plus 45° conical cap (captures sun+carrier).
    // The cap begins above the gears by clear_z.
    union() {
        cylinder(h=z_lip_start, r=post_r);
        translate([0,0,z_lip_start])
            cylinder(h=lip_h, r1=post_r, r2=post_r+lip_h);
    }
}

module housing() {
    union() {
        housing_shell();
        housing_post_and_cap();
    }
}

// ---------------------- Assembly ----------------------
module planetary_gearbox() {
    rp_s = m*z_sun/2;
    rp_p = m*z_planet/2;
    center_dist = rp_s + rp_p;

    planet_pos = [ for (i=[0:planets-1]) [ center_dist*cos(i*360/planets), center_dist*sin(i*360/planets) ] ];

    union() {
        housing();
        carrier();
        sun_gear();
        for (p=planet_pos) planet_gear(p);
    }
}

planetary_gearbox();
'}

